using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace TokenDock;

static class EditorChecks {
 static IEnumerable<T> Find<T>(DependencyObject root)where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);if(child is T match)yield return match;foreach(var nested in Find<T>(child))yield return nested;}}
 public static void Run(Action<bool> check,string dir){
  var p=new Preferences{Music=true,ClipboardHistory=true};p.MoveItem("opencode","claude");check(p.Visible.SequenceEqual(new[]{"opencode","claude","codex"}));p.MoveItem("opencode","codex",true);check(p.Visible[^1]=="opencode");
  p.ShowItem("codex",false);check(!p.IsShown("codex"));p.MoveItem("codex","claude");check(p.Visible[0]=="codex");p.MoveItem("clipboard","music");check(p.ModuleOrder[0]=="clipboard");
  p.MoveItem("codex","clipboard");check(Array.IndexOf(p.Layout,"codex")<Array.IndexOf(p.Layout,"clipboard"));string before=JsonSerializer.Serialize(p);p.MoveItem("untrusted",null);check(JsonSerializer.Serialize(p)==before);
  p.ShowItem("clipboard",false);check(!p.ClipboardHistory);p.MoveItem("clipboard",null);check(p.ClipboardHistory&&p.ModuleOrder[^1]=="clipboard");
  p.MusicTitle=false;p.MusicPreview=false;var restored=JsonSerializer.Deserialize<Preferences>(JsonSerializer.Serialize(p))!;restored.Normalize();check(!restored.MusicTitle&&!restored.MusicPreview&&restored.Visible.SequenceEqual(p.Visible));restored.ModuleOrder=["bad","clipboard","clipboard"];restored.Normalize();check(restored.ModuleOrder.SequenceEqual(new[]{"clipboard","music"}));
  int applied=0;var view=new PersonalizationView(new Preferences{Music=true,ClipboardHistory=true},_=>applied++,()=>{},()=>[]);view.Move("codex","claude");check(view.Draft.Visible[0]=="codex"&&applied==0);view.Remove("music");check(!view.Draft.Music&&applied==0);view.Move("music","clipboard");check(view.Draft.Music&&applied==0);
  void Render(string name){var host=new Border{Background=new SolidColorBrush(Color.FromRgb(20,20,25)),Padding=new Thickness(18),Child=view};host.Measure(new Size(492,double.PositiveInfinity));host.Arrange(new Rect(new Size(492,host.DesiredSize.Height)));host.UpdateLayout();var bitmap=new RenderTargetBitmap(492,(int)Math.Ceiling(host.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(host);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var file=File.Create(Path.Combine(dir,name));encoder.Save(file);host.Child=null;}
  Render("editor-vertical.png");foreach(var tile in Find<Button>(view).Where(b=>b.Uid=="rail"))foreach(var image in Find<Image>(tile)){check(Math.Max(image.ActualWidth,image.ActualHeight)>=23.9&&Math.Abs(image.ActualWidth/image.ActualHeight-image.Source.Width/image.Source.Height)<.01);check(image.ActualWidth<=tile.ActualWidth&&image.ActualHeight<=tile.ActualHeight);}check(Find<ComboBox>(view).Count()==0);check(Find<Expander>(view).Count()==0);
  var horizontal=Find<Button>(view).Single(b=>b.Content is string s&&s=="Horizontal");horizontal.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Render("editor-horizontal.png");check(view.Draft.Visible[0]=="codex");
  Find<Button>(view).Single(b=>System.Windows.Automation.AutomationProperties.GetName(b)=="Advanced settings").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Render("editor-options.png");
  var library=Find<Button>(view).Single(b=>b.Tag is string id&&id=="clipboard"&&b.Uid=="library");library.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(!view.Draft.ClipboardHistory);
  view.Move("cat","codex");view.Move("clipboard","cat");check(view.Draft.Layout.Take(2).SequenceEqual(new[]{"clipboard","cat"}));Render("editor-free-order.png");
  var mixed=new Preferences{Music=true,ClipboardHistory=true};foreach(var id in new[]{"cat","clipboard","codex","music","claude","opencode"})mixed.MoveItem(id,null);check(mixed.Layout.SequenceEqual(new[]{"cat","clipboard","codex","music","claude","opencode"}));
  var unified=new NotchSurface{Running=false};unified.SetFixture();unified.Configure(mixed);
  foreach(string edge in new[]{"top","bottom","left","right"})foreach(double open in new[]{0d,1d}){unified.SetEdge(edge);unified.Open=open;double previous=-1;foreach(string id in mixed.Layout){var r=unified.ItemBounds(id);double position=edge is "left" or "right"?r.Y+r.Height/2:r.X+r.Width/2;check(position>previous);previous=position;check(new[]{r.TopLeft,r.TopRight,r.BottomLeft,r.BottomRight}.All(unified.Contains));var center=new Point(r.X+r.Width/2,r.Y+r.Height/2);if(id is "music" or "clipboard")check(unified.ActionAt(center)==id);else if(mixed.Ids.Contains(id)){unified.SelectHover(center);check(unified.Selected==Array.IndexOf(mixed.Ids,id));}}unified.RenderFile(Path.Combine(dir,$"free-order-{edge}-{open}.png"),open==1,edge);}
  using var copies=new ClipboardModule();copies.History.Add("Fixture");unified.SetEdge("right");unified.Open=1;unified.ShowModule("clipboard",new InlineModuleView(null,copies));var body=unified.ModuleBounds;var icon=unified.ItemBounds("clipboard");check(body.Top<=icon.Y+icon.Height/2&&body.Bottom>=icon.Y+icon.Height/2);check(new[]{body.TopLeft,body.TopRight,body.BottomLeft,body.BottomRight}.All(unified.Contains));unified.RenderFile(Path.Combine(dir,"free-order-clipboard.png"),true,"right");unified.CloseModule();
  mixed.ShowItem("cat",false);check(!mixed.Layout.Contains("cat"));mixed.ShowItem("cat",true);check(mixed.Layout[0]=="cat");var roundtrip=JsonSerializer.Deserialize<Preferences>(JsonSerializer.Serialize(mixed))!;roundtrip.Normalize();check(roundtrip.Layout.SequenceEqual(mixed.Layout));
  var surface=new NotchSurface{Running=false};surface.Configure(new Preferences{Music=true,ClipboardHistory=true,ModuleOrder=["clipboard","music"]});foreach(string edge in new[]{"top","bottom","left","right"}){surface.SetEdge(edge);surface.Open=1;var clip=surface.ModuleRect("clipboard");var music=surface.ModuleRect("music");check(edge is "left" or "right"?clip.Y<music.Y:clip.X<music.X);check(surface.ActionAt(new Point(clip.X+16,clip.Y+16))=="clipboard");}
 }
}
